from __future__ import annotations
from dataclasses import dataclass
from typing import Iterable, Sequence, Tuple

@dataclass
class DisjointSet:
    parent: list[int]
    rank: list[int]

    @classmethod
    def create(cls, size: int) -> "DisjointSet":
        return cls(list(range(size)), [0] * size)

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        a, b = self.find(a), self.find(b)
        if a == b:
            return
        if self.rank[a] < self.rank[b]:
            a, b = b, a
        self.parent[b] = a
        if self.rank[a] == self.rank[b]:
            self.rank[a] += 1

def first_horizontal_crossing_threshold(
    n: int, keys: Sequence[Sequence[float]]
) -> float | None:
    """Return the first key level producing a left-to-right site crossing."""
    if n <= 0 or len(keys) != n or any(len(row) != n for row in keys):
        raise ValueError("keys must be a nonempty n by n array")
    left, right = n * n, n * n + 1
    dsu = DisjointSet.create(n * n + 2)
    active = [False] * (n * n)
    ordered = sorted((keys[r][c], r, c) for r in range(n) for c in range(n))
    for key, row, col in ordered:
        index = row * n + col
        active[index] = True
        if col == 0:
            dsu.union(index, left)
        if col == n - 1:
            dsu.union(index, right)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = row + dr, col + dc
            if 0 <= rr < n and 0 <= cc < n:
                neighbor = rr * n + cc
                if active[neighbor]:
                    dsu.union(index, neighbor)
        if dsu.find(left) == dsu.find(right):
            return key
    return None

